    #include <ctime>
    #include <cstdio>

    int main() {
        srand(time(0));
        for (int i = 0; i < 10; ++i) {
            print("%d\n", rand());
        }
        return 0;
    }

这段程序使用系统当前时间作随机数种子，然后使用rand()生成10个随机数。

STL中的随机数用法

